import{_ as e,H as o,f as n,i as r}from"./chunks/framework.Cg_xE-de.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"installation/forwarding-with-nginx-proxy-manager.md","filePath":"installation/forwarding-with-nginx-proxy-manager.md"}'),a={name:"installation/forwarding-with-nginx-proxy-manager.md"};function i(s,t,l,p,d,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<p>If you want to forward htmlOS NEXT securely from anywhere using a custom domain (e.g., <code>next.yourdomain.com</code>), you can route your traffic through <strong>Nginx Proxy Manager (NPM)</strong>.</p><p>This guide will walk you through configuring <strong>htmlOS NEXT</strong> to be forwarded by <strong>NPM</strong>.</p><h2 id="step-1-forward-the-frontend" tabindex="-1">Step 1: Forward the frontend <a class="header-anchor" href="#step-1-forward-the-frontend" aria-label="Permalink to &quot;Step 1: Forward the frontend&quot;">​</a></h2><p>Open your <strong>Nginx Proxy Manager</strong> interface and select <strong>Proxy Hosts</strong>.</p><p>![[Pasted image 20260528211646.png|387]]</p><p>Then click the <strong>Add Proxy Host</strong> button.</p><p>Then fill in the details:</p><ul><li>The domain name you wish to forward to</li><li>The hostname and port where the frontend is located</li><li>Block Common Exploits (optional)</li></ul><p>![[Pasted image 20260528211926.png|460]]</p><p>If you want HTTPS support, switch to the <strong>SSL</strong> tab, and:</p><ul><li>Select your SSL certificate</li><li>Enable <strong>Force SSL</strong></li><li>Enable <strong>HTTP/2 Support</strong></li></ul><p>![[Pasted image 20260528212202.png|463]]</p><p>Click the <strong>Save</strong> button.</p><h2 id="step-2-forward-the-backend" tabindex="-1">Step 2: Forward the backend <a class="header-anchor" href="#step-2-forward-the-backend" aria-label="Permalink to &quot;Step 2: Forward the backend&quot;">​</a></h2><p>Click the <strong>Add Proxy Host</strong> button.</p><p>Then fill in the details:</p><ul><li>The domain name you wish to forward to</li><li>The hostname and port where the backend is located</li><li>Block Common Exploits (optional)</li><li>Websockets Support (needed for the continuity feature)</li></ul><p>![[Pasted image 20260528212441.png|462]]</p><p>If you want HTTPS support, switch to the <strong>SSL</strong> tab, and:</p><ul><li>Select your SSL certificate</li><li>Enable <strong>Force SSL</strong></li><li>Enable <strong>HTTP/2 Support</strong></li></ul><p>![[Pasted image 20260528212202.png|467]]</p><p>Click the <strong>Save</strong> button.</p><h2 id="step-3-update-the-environment-variables" tabindex="-1">Step 3: Update the environment variables <a class="header-anchor" href="#step-3-update-the-environment-variables" aria-label="Permalink to &quot;Step 3: Update the environment variables&quot;">​</a></h2><p>On your Docker Compose file, change these variables:</p><ul><li><code>FRONTEND_ADDRESSES</code>: To the domain you just gave the frontend.</li><li><code>VITE_BACKEND_ADDRESSES</code>: To the domain you just gave the backend.</li></ul><p>Then restart your Docker Compose stack.</p><p>After these changes, you should now be able to access your <strong>htmlOS NEXT</strong> instance from your domain.</p>',27)])])}const u=e(a,[["render",i]]);export{c as __pageData,u as default};
